def act(post, d):
    v, sev = d["violation"], d["severity"].score

    if d["minor_involved"].noul >= 0.2:
        return escalate(post, d.id)                  # always a person, low bar
    if v.abstain:
        return review_queue.add(post, decision_id=d.id)
    if v.choice == "none":
        return publish(post)
    if sev >= 3.5:
        return escalate(post, d.id)                  # Critical
    if sev >= 1.5:
        return remove(post, decision_id=d.id)        # Medium and up
    return publish(post)                             # Low: borderline, leave up
